-- The Agent's Ascent — course content (generated by build/build_course_db.py from build/course.md; do not edit by hand).
-- Run supabase/course.sql once first (tables and functions); run this file whenever the course changes.
-- Course version 1.
begin;
insert into public.course_meta (id, version, released, title, page) values (1, 1, '2026-10-08', 'Novice to Agentic AI Developer — Fast-Track Curriculum', 'https://paulcachia.github.io/agents-ascent/course.html')
  on conflict (id) do update set version = excluded.version, released = excluded.released, title = excluded.title, page = excluded.page, updated_at = now();
insert into public.course_phases (id, pos, title, timing, land, weeks, intro, outro)
  select id, pos, title, timing, land, weeks, intro, outro from jsonb_populate_recordset(null::public.course_phases, $ph$[{"id": "p0", "pos": 0, "title": "Phase 0 – Orientation", "timing": "Week 1, ~6 hours", "land": "Base Camp", "weeks": "Week 1", "intro": "**Objectives:** understand what vibe coding and agentic engineering mean, where the field is in late 2026, and how to learn with an AI pair. **Prerequisites:** none.", "outro": ""}, {"id": "p1", "pos": 1, "title": "Phase 1 – Computer Foundations", "timing": "Weeks 1–3, ~24 hours; Module 1.4 Part B lands in Week 11", "land": "Foothills", "weeks": "Weeks 1–3", "intro": "**Objectives:** use the terminal on macOS or Windows/WSL; understand file systems and environment variables; install software with Homebrew or winget; work in VS Code; use Git and GitHub properly, including SSH keys, conflicts, rebase, pull request review, Issues/Projects and the GitHub CLI; understand HTTP, DNS, client/server and hosting. **Prerequisites:** Phase 0.", "outro": "**Phase 1 project:** create a repo, clone it over SSH, write a README in VS Code, then commit, push, open a PR and merge it.\n\n**Ready to move on when…** you can do that without notes; explain what happens between typing a URL and seeing the page (DNS → server → HTTP response); set and read an environment variable; resolve a conflict without panic; explain merge vs rebase in one sentence each; recover a \"lost\" commit from reflog; review and squash-merge an agent's PR with at least one requested change; and `main` cannot be pushed to directly.\n\n**Pitfalls:** fighting Windows instead of using WSL; committing `.env` files (add `.gitignore` first); running commands you don't understand (ask Claude to \"explain each flag\" first); rebasing a branch someone else has pulled; treating green CI as approval (tests check what's there, not what's missing); `--force` instead of `--force-with-lease`; and installing GitHub Apps without reading the permission list. The Claude GitHub App asks for a single permission set covering all Claude features, including read-and-write on Actions, Contents, Issues, Pull requests and Workflows, and GitHub won't let you accept a subset. For tighter scope you can build a custom app with only Contents, Issues and Pull requests, though that covers only the Action, not Code Review."}, {"id": "p2", "pos": 2, "title": "Phase 2 – Programming Foundations, Fast", "timing": "Weeks 4–7, ~45 hours", "land": "Code Forest", "weeks": "Weeks 4–7", "intro": "**Objectives:** read and debug Python and TypeScript; use virtual environments and `uv`/`pip`; call APIs and handle JSON; understand async basics; use Node.js and npm/pnpm; know just enough HTML/CSS. The aim is to read code, not memorise it. **Prerequisites:** Phase 1.", "outro": "**How to learn with AI here:** ask \"explain this line by line\", \"what breaks if I remove X?\" and \"write a failing test that shows the bug\". Have it quiz you. Don't ask it to \"just fix it\" until you can say what's wrong.\n\n**Phase 2 project:** a Python CLI and a small TypeScript script that both call the same API, each committed with a README.\n\n**Ready to move on when…** you can take a 100-line file you didn't write, explain what it does, find where it reads the API key, and fix a planted bug with the AI's help while giving the explanation yourself.\n\n**Pitfalls:** tutorial hell (cap this phase at about 45 hours), memorising syntax, and skipping virtual environments."}, {"id": "p3", "pos": 3, "title": "Phase 3 – How LLMs Work, Practically", "timing": "Week 8, ~15 hours", "land": "Model Ridge", "weeks": "Week 8", "intro": "**Objectives:** understand tokens, context windows, embeddings, temperature, system prompts, tool calling, structured outputs, hallucination, cost, the model landscape, and prompt and context engineering. **Prerequisites:** Phase 2.", "outro": ""}, {"id": "p4", "pos": 4, "title": "Phase 4 – AI-Assisted Coding Tools", "timing": "Weeks 2 and 9–11, ~30 hours", "land": "Claude Pass", "weeks": "Weeks 9–11", "intro": "**Speed hack:** in week 2, alongside Phase 1, do Module 4.1's first video and deploy a tiny static site to Vercel. Early wins keep you going.\n\n**Objectives:** become fluent in Claude Code (CLAUDE.md, slash commands, hooks, subagents, skills, plugins, MCP, headless/CI, the Agent SDK) and know the alternatives. **Prerequisites:** Phase 1.", "outro": "**Ready to move on when…** you can start from a fresh repo and, with only Claude Code plus your own review, ship a feature on a branch with tests, a hook-enforced lint and a PR, and explain every file that changed.\n\n**Pitfalls:** clicking \"accept all\" on database or infrastructure commands, letting CLAUDE.md grow to 2,000 lines, installing dozens of random MCP servers (each is a supply-chain and prompt-injection risk), and tool FOMO."}, {"id": "p5", "pos": 5, "title": "Phase 5 – Building Real Apps", "timing": "Weeks 12–17, ~60 hours", "land": "SaaS Cliffs", "weeks": "Weeks 12–17", "intro": "**Objectives:** build with Next.js/React and TypeScript; use Postgres via Supabase or Neon, plus auth; take payments with Stripe; deploy to Vercel, Railway, Fly.io or Cloudflare; learn Docker basics and manage secrets; add testing, CI/CD with GitHub Actions, and monitoring; apply vibe-coding security basics; finish with a SaaS that takes real money. **Prerequisites:** Phases 2 and 4.", "outro": ""}, {"id": "p6", "pos": 6, "title": "Phase 6 – Building AI Agents", "timing": "Weeks 17–22, ~60 hours", "land": "Agent Forge", "weeks": "Weeks 17–22", "intro": "**Objectives:** use the Claude and OpenAI APIs, including tool use; understand the agent loop and Anthropic's \"Building effective agents\" patterns; build and use MCP servers; compare agent frameworks; add RAG, memory and structured outputs; set up evals, observability, guardrails and cost control; run background agents, and know when computer-use or browser agents fit. **Prerequisites:** Phases 3–5.", "outro": ""}, {"id": "p7", "pos": 7, "title": "Phase 7 – Automation and Multi-Agent Business Systems", "timing": "Weeks 22–25, ~30 hours", "land": "Orchestration", "weeks": "Weeks 22–25", "intro": "**Objectives:** n8n, Make and Zapier; orchestration; connecting to email, CRM, Slack and Notion; scheduled agents; human-in-the-loop design; an \"AI-run business\" stack and its limits. **Prerequisites:** Phase 6.", "outro": ""}, {"id": "p8", "pos": 8, "title": "Phase 8 – Shipping, Product and Entrepreneurship", "timing": "Weeks 25–26 and ongoing, ~50 hours with capstones", "land": "Launch Pad", "weeks": "Weeks 25–26", "intro": "**Objectives:** idea validation, MVP scoping, analytics, landing pages, marketing automation, pricing, UK/EU legal basics, building in public. Your sales background is a big advantage here.", "outro": ""}]$ph$::jsonb)
  on conflict (id) do update set pos = excluded.pos, title = excluded.title, timing = excluded.timing, land = excluded.land, weeks = excluded.weeks, intro = excluded.intro, outro = excluded.outro;
insert into public.course_camps (key, pos, phase, title, week_label, week, hours, video_min, vids, core, capstone, body, items, exercises, ready, pitfalls, changed_in)
  select key, pos, phase, title, week_label, week, hours, video_min, vids, core, capstone, body, items, exercises, ready, pitfalls, changed_in from jsonb_populate_recordset(null::public.course_camps, $cc$[{"key": "m00", "pos": 0, "phase": "p0", "title": "Orientation: vibe coding vs agentic engineering", "week_label": "Week 1", "week": 1, "hours": 6, "video_min": 180, "vids": "Karpathy, Vibe Coding → Agentic Engineering 30 m · DLAI Claude Code (first 2 lessons) ~1 h · AI Fluency ~1–2 h", "core": true, "capstone": false, "body": "#### Key context\n\n- **Origin:** Andrej Karpathy coined \"vibe coding\" in a post on X on 2 February 2025, meaning it for throwaway weekend projects. Collins English Dictionary made it Word of the Year for 2025 (CNN, 6 November 2025).\n- **The 2026 shift:** at Sequoia's AI Ascent (released 29 April 2026), Karpathy separated the two ideas. Vibe coding raises the floor; agentic engineering is about preserving the quality bar of professional software. His written summary calls the agent fallible and stochastic and says the agentic engineer does not blindly accept generated code. Secondary sources report he joined Anthropic's pre-training team in May 2026, worth bearing in mind when he talks about Claude.\n- **Model landscape in late 2026 (from release trackers, so check vendor pages):** Anthropic shipped Claude Fable 5.1 and Claude Mythos 5.1 (restricted) on 1 September, Claude Opus 5.5 on 22 September and, per one tracker, Claude Sonnet 5.5 on 28 September. OpenAI shipped GPT-6 Astra on 3 September, GPT-6 Sol and Luna on 22 September and GPT-6.1 Sol on 29 September. Google shipped Gemini 3.8 Flash on 2 September; trackers disagree on whether \"Gemini 4 Argon\" (30 September) has shipped. Open-weight options include DeepSeek V4.1, Qwen 3.8 and Mistral Large 4.\n- **What this means for you:** frontier models change every few weeks. Learn concepts and workflows rather than model names.", "items": [{"title": "Andrej Karpathy: From Vibe Coding to Agentic Engineering", "creator": "Sequoia Capital", "url": "https://www.youtube.com/watch?v=96jN2OCOfLs", "link": "", "len": "29:49", "date": "29 Apr 2026", "cost": "Free", "why": "**Primary.** The framing from the man who coined the term. 15:46 onwards is the core.", "status": "✔", "kind": "video", "id": "m00.andrej-karpathy-vibe-coding-agentic"}, {"title": "Sequoia Ascent 2026 summary", "creator": "Karpathy (blog)", "url": "https://karpathy.bearblog.dev/sequoia-ascent-2026/", "link": "", "len": "~20 min read", "date": "2026", "cost": "Free", "why": "His own cleaned-up transcript. Keep section 7.", "status": "✔", "kind": "course", "id": "m00.sequoia-ascent-2026-summary"}, {"title": "Claude Code: A Highly Agentic Coding Assistant (first 2 lessons now)", "creator": "DeepLearning.AI × Anthropic", "url": "https://www.deeplearning.ai/courses/claude-code-a-highly-agentic-coding-assistant", "link": "", "len": "~1–2 h total", "date": "Aug 2025", "cost": "Free", "why": "Shows how simple an agent's architecture is: a few search, list and read tools. Takes away the \"magic\".", "status": "✔", "kind": "course", "id": "m00.claude-code-highly-agentic-coding"}, {"title": "AI Fluency: Framework & Foundations", "creator": "Claude Academy", "url": "https://academy.claude.com", "link": "", "len": "~1–2 h", "date": "relaunched 20 Aug 2026", "cost": "Free", "why": "A short \"4D\" model for working with AI. Skip the educator and nonprofit variants.", "status": "✔", "kind": "course", "id": "m00.ai-fluency-framework-foundations"}], "exercises": [{"text": "write a one-page \"learning contract\": three products you want to build, your weekly hours, and one rule: *I never ship code I cannot get the agent to explain to me.*", "id": "m00.ex1"}], "ready": "you can explain to a non-technical co-founder how vibe coding (prototype, accept all changes) differs from agentic engineering (write a spec, review diffs, run tests and evals).", "pitfalls": "binge-watching hype videos, hopping between tools, and believing \"no-code\" means \"no understanding needed\".", "changed_in": 1}, {"key": "m01", "pos": 1, "phase": "p1", "title": "1.1 Terminal, file system, package managers", "week_label": "Week 1", "week": 1, "hours": 6, "video_min": 190, "vids": "60 Linux commands 10 m · Linux for Hackers series ~3 h (length unverified) · WSL/Homebrew docs", "core": true, "capstone": false, "body": "", "items": [{"title": "60 Linux Commands you NEED to know (in 10 minutes)", "creator": "NetworkChuck", "url": "https://www.youtube.com/watch?v=gd7BXuUQ91w", "link": "", "len": "~10 min", "date": "~2021–23 (older, foundational)", "cost": "Free", "why": "The fastest tour of commands that also work in the macOS terminal.", "status": "✔ exists", "kind": "video", "id": "m01.60-linux-commands-you-need"}, {"title": "Linux for Hackers EP 1 (8+ episode series)", "creator": "NetworkChuck", "url": "https://www.youtube.com/watch?v=VbEx7B_PTOE", "link": "", "len": "not confirmed", "date": "~2021–23 (older, foundational)", "cost": "Free", "why": "Watch EP1–2 for shell basics. Skip the \"hacking\" episodes.", "status": "✔ exists", "kind": "video", "id": "m01.linux-hackers-ep-1"}, {"title": "Install WSL", "creator": "Microsoft Learn", "url": "https://learn.microsoft.com/windows/wsl/install", "link": "", "len": "Reference", "date": "Current", "cost": "Free", "why": "**Windows users: do all development inside WSL (Ubuntu).** Agent tooling assumes a Unix shell.", "status": "◐", "kind": "reading", "id": "m01.install-wsl"}, {"title": "Homebrew / winget", "creator": "Official", "url": "https://brew.sh", "link": "https://brew.sh · https://learn.microsoft.com/windows/package-manager/", "len": "Reference", "date": "Current", "cost": "Free", "why": "Install everything through a package manager.", "status": "◐", "kind": "reading", "id": "m01.homebrew-winget"}], "exercises": [{"text": "in the terminal, create `~/code/sandbox`, make some files, set an environment variable, print it and add it to your shell profile. Then remove it again, and learn why secrets shouldn't live in profiles that get synced.", "id": "m01.ex1"}], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m02", "pos": 2, "phase": "p1", "title": "1.2 VS Code, Git & GitHub basics, SSH", "week_label": "Week 2", "week": 2, "hours": 6, "video_min": 83, "vids": "Git & GitHub crash course 1 h 08 m · GitHub for Beginners: Git in VS Code 15 m · VS Code docs", "core": true, "capstone": false, "body": "", "items": [{"title": "Git and GitHub for Beginners – Crash Course", "creator": "freeCodeCamp (Gwen Faraday)", "url": "https://www.youtube.com/watch?v=RGOj5yH7evk", "link": "", "len": "~1 h 08 m", "date": "~2020 (older, foundational)", "cost": "Free", "why": "**Primary.** Commits, branches, PRs and SSH. Skip password auth; use SSH or the GitHub CLI instead.", "status": "✔", "kind": "video", "id": "m02.git-github-beginners-crash-course"}, {"title": "GitHub for Beginners S3: Git and GitHub in VS Code", "creator": "GitHub (Kedasha Kerr)", "url": "https://github.blog/developer-skills/github/github-for-beginners-getting-started-with-git-and-github-in-vs-code/", "link": "", "len": "~15 min", "date": "25 May 2026", "cost": "Free", "why": "Stage, commit, push and review diffs from the editor.", "status": "✔", "kind": "course", "id": "m02.github-beginners-git-github-vs"}, {"title": "VS Code Docs", "creator": "Microsoft", "url": "https://code.visualstudio.com/docs", "link": "", "len": "Reference/videos", "date": "Current", "cost": "Free", "why": "Learn the integrated terminal, Source Control panel and extensions.", "status": "◐", "kind": "reading", "id": "m02.vs-code-docs"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m03", "pos": 3, "phase": "p1", "title": "1.3 How the web works", "week_label": "Week 3", "week": 3, "hours": 4, "video_min": 2, "vids": "DNS in 100 seconds 2 m · MDN How the web works (reading, most of the 4 h)", "core": true, "capstone": false, "body": "", "items": [{"title": "DNS Explained in 100 Seconds", "creator": "Fireship", "url": "https://www.youtube.com/watch?v=UVR9lhUGAyU", "link": "", "len": "~2 min", "date": "not confirmed (older, foundational)", "cost": "Free", "why": "The fastest mental model of DNS. Then watch Fireship's other \"100 Seconds\" videos (HTTP, REST, JSON) as each comes up.", "status": "✔", "kind": "video", "id": "m03.dns-explained-100-seconds"}, {"title": "MDN – Learn web development / HTTP", "creator": "Mozilla", "url": "https://developer.mozilla.org/en-US/docs/Learn", "link": "", "len": "Reading", "date": "Current", "cost": "Free", "why": "The best free reference on HTTP methods, status codes and headers.", "status": "◐", "kind": "reading", "id": "m03.mdn-learn-web-development-http"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m04", "pos": 4, "phase": "p1", "title": "1.4A Git depth: conflicts, rebase, reflog", "week_label": "Week 3", "week": 3, "hours": 5, "video_min": 100, "vids": "Rebase in 6 min 7 m · Merge vs rebase 8 m · Git for Professionals 41 m · Advanced Git 35 m · 13 Git techniques 8 m · Learn Git Branching ~2 h (interactive) · Oh Shit, Git 15 m", "core": true, "capstone": false, "body": "**Objectives:** resolve merge conflicts calmly, know when to merge vs rebase, tidy history with interactive rebase and recover anything with reflog; review a pull request properly, including PRs an agent wrote (read the diff, run it, comment inline, request changes, approve, squash-merge); run a project with Issues, Projects boards, labels and `Closes #n` automation, which becomes the task queue your agents work from; use the GitHub CLI (`gh`), which Claude Code itself depends on; protect `main` with rulesets, required checks, secret scanning and push protection; connect Claude Code to GitHub with `/install-github-app`, `@claude` in issues and PRs, automatic code review, and worktrees for running agents in parallel.", "items": [{"title": "Learn Git Rebase in 6 minutes // explained with live animations!", "creator": "The Modern Coder", "url": "https://www.youtube.com/watch?v=f1wnYdLEpgI", "link": "", "len": "6:43", "date": "Nov 2017 (older, foundational)", "cost": "Free", "why": "The best-rated rebase explainer on YouTube; the animations make it click.", "status": "✔", "kind": "video", "id": "m04.learn-git-rebase-6-minutes"}, {"title": "Git MERGE vs REBASE: The Definitive Guide", "creator": "The Modern Coder", "url": "https://www.youtube.com/watch?v=zOnwgxiC0OA", "link": "", "len": "~8 min", "date": "~2023", "cost": "Free", "why": "3-way vs fast-forward merge, the rebase workflow, and the \"rebase pitfalls\" chapter at 6:41.", "status": "✔", "kind": "video", "id": "m04.git-merge-vs-rebase-definitive"}, {"title": "Git for Professionals Tutorial", "creator": "freeCodeCamp (Tobias Günther)", "url": "https://www.youtube.com/watch?v=Uszj_k0DGsg", "link": "", "len": "40:42", "date": "2021 (older, foundational)", "cost": "Free", "why": "The \"undo anything\" toolkit: branching strategies, conflicts, stash, reflog.", "status": "✔", "kind": "video", "id": "m04.git-professionals-tutorial"}, {"title": "Advanced Git Tutorial – Interactive Rebase, Cherry-Picking, Reflog, Submodules", "creator": "freeCodeCamp (Tobias Günther)", "url": "https://www.freecodecamp.org/news/advanced-git-interactive-rebase-cherry-picking-reflog-and-more/", "link": "", "len": "~35 min", "date": "Nov 2021", "cost": "Free", "why": "Squash an agent's 12 messy commits into 2. Skip the submodules section.", "status": "✔", "kind": "course", "id": "m04.advanced-git-tutorial-interactive-rebase"}, {"title": "13 Advanced (but useful) Git Techniques and Shortcuts", "creator": "Fireship", "url": "https://www.youtube.com/watch?v=ecK3EnyGD8o", "link": "", "len": "8:07", "date": "7 Sep 2021", "cost": "Free", "why": "Aliases, amend, revert vs reset, stash, bisect, hooks.", "status": "✔", "kind": "video", "id": "m04.13-advanced-git-techniques-shortcuts"}, {"title": "Learn Git Branching", "creator": "learngitbranching.js.org", "url": "https://learngitbranching.js.org", "link": "", "len": "~2 h", "date": "Ongoing", "cost": "Free", "why": "Practise rebase and cherry-pick on a visual graph. Do \"Ramping Up\" and \"Moving Work Around\".", "status": "◐", "kind": "course", "id": "m04.learn-git-branching"}, {"title": "Oh Shit, Git!?!", "creator": "ohshitgit.com", "url": "https://ohshitgit.com", "link": "", "len": "15 min", "date": "Ongoing", "cost": "Free", "why": "The panic page. Bookmark it.", "status": "◐", "kind": "course", "id": "m04.oh-shit-git"}, {"title": "GitHub Skills: Resolve merge conflicts", "creator": "GitHub", "url": "https://github.com/skills", "link": "https://github.com/skills (catalogue now at https://learn.github.com/skills)", "len": "<1 h", "date": "Current", "cost": "Free", "why": "Hands-on in your own repo, graded by Actions. Free in public repositories.", "status": "✔ exists", "kind": "course", "id": "m04.github-skills-resolve-merge-conflicts"}], "exercises": [{"text": "**Conflicts and recovery.** In your sandbox repo, create two branches that edit the same line. Merge one; rebase the other onto `main` and resolve the conflict in VS Code's merge editor. Squash the branch to a single commit with `git rebase -i`. Then \"break\" `main` with `git reset --hard HEAD~3` and recover it from `git reflog`.", "id": "m04.ex1"}], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m05", "pos": 5, "phase": "p2", "title": "2.1 Python from zero", "week_label": "Weeks 4–5", "week": 5, "hours": 20, "video_min": 1080, "vids": "Mosh, Python Full Course 2 h · Harvard CS50P ~16 h", "core": true, "capstone": false, "body": "", "items": [{"title": "Python Full Course for Beginners", "creator": "Programming with Mosh", "url": "https://www.youtube.com/watch?v=K5KVEU3aaeQ", "link": "", "len": "~2 h", "date": "labelled 2025", "cost": "Free", "why": "**Primary fast track.** Enough to read agent code.", "status": "✔ exists", "kind": "video", "id": "m05.python-full-course-beginners"}, {"title": "Harvard CS50P – Introduction to Programming with Python", "creator": "David J. Malan via freeCodeCamp", "url": "https://www.youtube.com/watch?v=nLRL_NcnK-4", "link": "https://www.youtube.com/watch?v=nLRL_NcnK-4 (playlist: https://www.youtube.com/playlist?list=PLhQjrBD2T3817j24-GogXmWqO5Q5vYy0V; problem sets: https://pll.harvard.edu/course/cs50s-introduction-programming-python)", "len": "~16 h", "date": "~2022–23 (older, foundational)", "cost": "Free (paid edX cert optional)", "why": "**For depth:** lectures on functions, exceptions, libraries, file I/O and OOP, plus 3–4 problem sets with the AI explaining, not solving.", "status": "✔", "kind": "video", "id": "m05.harvard-cs50p-introduction-programming"}, {"title": "uv docs", "creator": "Astral", "url": "https://docs.astral.sh/uv/", "link": "", "len": "Reference", "date": "Current", "cost": "Free", "why": "The fast default for Python projects in 2026: `uv init`, `uv add`, `uv run`.", "status": "◐", "kind": "reading", "id": "m05.uv-docs"}], "exercises": [{"text": "write a Python script that calls a public JSON API and writes the results to a CSV. Then make an `asyncio` version that fetches 5 cities at once.", "id": "m05.ex1"}], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m06", "pos": 6, "phase": "p2", "title": "2.2 TypeScript & Node", "week_label": "Week 6", "week": 6, "hours": 18, "video_min": 210, "vids": "Beginner's TypeScript, 18 video exercises ~3–4 h · Node/npm docs", "core": true, "capstone": false, "body": "", "items": [{"title": "Beginner's TypeScript (18 exercises)", "creator": "Matt Pocock / Total TypeScript", "url": "https://www.totaltypescript.com/tutorials/beginners-typescript", "link": "", "len": "~3–4 h", "date": "Sep 2022 (older, foundational)", "cost": "Free", "why": "**Primary.** Types are the cheapest way to catch AI mistakes. Skip the paid Pro workshops. Pair it with https://nodejs.org/en/learn for modules, npm scripts and `.env`.", "status": "✔", "kind": "course", "id": "m06.beginner-s-typescript"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m07", "pos": 7, "phase": "p2", "title": "2.3 HTML/CSS & reading code", "week_label": "Week 7", "week": 7, "hours": 7, "video_min": 90, "vids": "Claude Code for Beginners, debugging & navigation sections ~1.5 h · MDN HTML & CSS ~4 h (reading)", "core": false, "capstone": false, "body": "", "items": [{"title": "MDN – HTML & CSS basics", "creator": "Mozilla", "url": "https://developer.mozilla.org/en-US/docs/Learn", "link": "", "len": "~4 h", "date": "Current", "cost": "Free", "why": "Box model, flexbox and semantic tags. Tailwind/shadcn handle the rest.", "status": "◐", "kind": "course", "id": "m07.mdn-html-css-basics"}, {"title": "Claude Code for Beginners (debugging and navigation sections)", "creator": "freeCodeCamp", "url": "https://www.freecodecamp.org/news/claude-code-for-beginners/", "link": "", "len": "4 h 27 m (~1.5 h here)", "date": "14 May 2026", "cost": "Free", "why": "Using the agent to explain a codebase you've never seen.", "status": "✔", "kind": "course", "id": "m07.claude-code-beginners"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m08", "pos": 8, "phase": "p3", "title": "3 How LLMs work, practically", "week_label": "Week 8", "week": 8, "hours": 15, "video_min": 211, "vids": "Karpathy, Deep Dive into LLMs 3 h 31 m · Building with the Claude API course (several h) · Effective context engineering 30 m (reading)", "core": true, "capstone": false, "body": "**Cost intuition (from third-party trackers such as https://benchr.org/timeline, so verify):** prices per million input/output tokens vary about 100×. GPT-6 Luna is about $0.10 / $0.50; Claude Sonnet 5.5 about $2 / $10; Claude Opus 5.5 about $4 / $20; GPT-6 Astra about $10 / $50. Send easy steps to cheap models and save frontier models for planning and review. That is the biggest cost lever in agent systems.", "items": [{"title": "Deep Dive into LLMs like ChatGPT", "creator": "Andrej Karpathy", "url": "https://www.youtube.com/watch?v=7xTGNNLPyMI", "link": "", "len": "3 h 31 m", "date": "5 Feb 2025", "cost": "Free", "why": "**Primary.** Pre-training, tokens, fine-tuning (SFT) and RL, plus the best explanation of *why* models hallucinate. Watch at 1.25×.", "status": "✔", "kind": "video", "id": "m08.deep-dive-into-llms-like"}, {"title": "Effective context engineering for AI agents", "creator": "Anthropic Applied AI team", "url": "https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents", "link": "", "len": "~30 min", "date": "29 Sep 2025", "cost": "Free", "why": "Moves past prompt engineering to curating everything that goes into the context window. Underpins CLAUDE.md, skills and subagents.", "status": "✔", "kind": "course", "id": "m08.effective-context-engineering-ai-agents"}, {"title": "Building with the Claude API", "creator": "Claude Academy", "url": "https://academy.claude.com", "link": "https://academy.claude.com (legacy: anthropic.skilljar.com/building-with-the-claude-api)", "len": "several h", "date": "2026", "cost": "Free", "why": "Hands-on tool use, structured outputs and caching.", "status": "✔", "kind": "course", "id": "m08.building-claude-api"}, {"title": "Prompting docs: Anthropic, OpenAI, Google", "creator": "Vendors", "url": "https://docs.anthropic.com", "link": "https://docs.anthropic.com · https://platform.openai.com/docs · https://ai.google.dev", "len": "Reading", "date": "Current", "cost": "Free", "why": "**For balance:** structured outputs and tool calling work much the same across vendors.", "status": "◐", "kind": "reading", "id": "m08.prompting-docs-anthropic-openai-google"}], "exercises": [{"text": "send the same prompt to two vendors and ask for schema-constrained JSON. Measure tokens and cost, then overfill a small context on purpose and watch the quality drop.", "id": "m08.ex1"}], "ready": "you can explain what tokens are, what temperature does, why with tool calling \"the model asks; your code executes\", and why bloated context makes agents worse.", "pitfalls": "treating models as databases of truth, ignoring cost, and chasing leaderboards.", "changed_in": 1}, {"key": "m09", "pos": 9, "phase": "p4", "title": "4.1 Claude Code deep dive", "week_label": "Weeks 9–10", "week": 10, "hours": 20, "video_min": 630, "vids": "Claude Code Full Course 1.5 h · Claude Code 101 1.5 h · Claude Code in Action 1 h · Agent Skills + Subagents 2 h · Claude Code for Beginners 4 h 27 m · optional deep dives: Essentials 12 h, Mosh 9 h", "core": true, "capstone": false, "body": "Claude Code runs in the terminal, in IDE extensions, as a desktop app and on the web. The free Claude plan does not include it.\n\n| Plan | Price | Usage |\n| --- | --- | --- |\n| Pro (the minimum) | $20/month, or $17/month billed annually | Rolling 5-hour windows plus weekly limits, shared with Claude chat |\n| Max 5x | $100/month | 5× Pro |\n| Max 20x | $200/month | 20× Pro |\n\n**Concepts to master, in order:**\n\n1. **CLAUDE.md:** short project memory covering architecture, commands and conventions.\n2. **Plan mode:** explore → plan → code → commit.\n3. **Permissions and sandboxing:** never use blanket \"skip permissions\" on a machine that holds production credentials.\n4. **Slash commands and Skills:** stored in `.claude/skills/<name>/SKILL.md`.\n5. **Hooks:** deterministic scripts that run at `PreToolUse`, `PostToolUse` or `Stop`, e.g. auto-format, block `rm -rf`, run tests. A hook always runs; a prompt is only a suggestion.\n6. **Subagents:** separate contexts for research, review and testing, which can run in parallel.\n7. **MCP servers:** connections to GitHub, Supabase, Playwright, Notion and so on.\n8. **Plugins:** shareable bundles of skills, hooks, agents and MCP config.\n9. **Headless/CI:** `claude -p` in scripts and GitHub Actions.\n10. **Claude Agent SDK:** the same harness, as a library. Renamed from \"Claude Code SDK\" on 29 September 2025, alongside Claude Code 2.0. The packages are now `claude-agent-sdk` and `@anthropic-ai/claude-agent-sdk`, so older tutorials import the wrong ones. Docs: https://code.claude.com/docs/en/agent-sdk/overview and the migration guide at https://platform.claude.com/docs/en/agent-sdk/migration-guide.", "items": [{"title": "Claude Code Full Course", "creator": "freeCodeCamp (Eric, ex-Amazon/Microsoft)", "url": "https://www.freecodecamp.org/news/claude-code-full-course/", "link": "", "len": "~1.5 h", "date": "5 Aug 2026", "cost": "Free", "why": "**Watch this first.** The newest full course: VS Code setup, `/goal`, Skills, MCP, GitHub, deployment.", "status": "✔", "kind": "course", "id": "m09.claude-code-full-course"}, {"title": "Claude Code for Beginners [Full Course]", "creator": "freeCodeCamp", "url": "https://www.freecodecamp.org/news/claude-code-for-beginners/", "link": "", "len": "4 h 27 m", "date": "14 May 2026", "cost": "Free", "why": "Good second pass: scaffolding, audits, debugging.", "status": "✔", "kind": "course", "id": "m09.claude-code-beginners-full-course"}, {"title": "Claude Code Essentials", "creator": "freeCodeCamp (Andrew Brown, ExamPro)", "url": "https://www.freecodecamp.org/news/claude-code-essentials/", "link": "", "len": "~12 h", "date": "Mar 2026", "cost": "Free", "why": "**The exhaustive reference:** permissions, sandboxing, dev containers, GitHub Actions, Agent SDK, memory, MCP, Git worktrees. Watch selectively.", "status": "✔", "kind": "course", "id": "m09.claude-code-essentials"}, {"title": "Claude Code 101", "creator": "Claude Academy", "url": "https://academy.claude.com/courses/claude-code-101", "link": "", "len": "~1.5 h", "date": "rebuilt 2026", "cost": "Free (exercises need Pro/API)", "why": "Official baseline, with a badge.", "status": "✔", "kind": "course", "id": "m09.claude-code-101"}, {"title": "Claude Code in Action", "creator": "Claude Academy", "url": "https://academy.claude.com/courses/claude-code-in-action", "link": "", "len": "~1 h, 9 lessons + quiz", "date": "2026", "cost": "Free", "why": "Context, custom commands, MCP, GitHub, hooks, SDK.", "status": "✔", "kind": "course", "id": "m09.claude-code-action"}, {"title": "Introduction to Agent Skills / Introduction to Subagents", "creator": "Claude Academy", "url": "https://academy.claude.com/courses/introduction-to-agent-skills", "link": "https://academy.claude.com/courses/introduction-to-agent-skills · https://academy.claude.com/courses/introduction-to-subagents", "len": "~1 h each", "date": "2026", "cost": "Free", "why": "Reusable SKILL.md packages; context isolation.", "status": "✔", "kind": "course", "id": "m09.introduction-agent-skills-introduction"}, {"title": "Claude Code: A Highly Agentic Coding Assistant", "creator": "DeepLearning.AI × Anthropic", "url": "https://www.deeplearning.ai/courses/claude-code-a-highly-agentic-coding-assistant", "link": "", "len": "~2 h", "date": "Aug 2025", "cost": "Free", "why": "Parallel sessions with worktrees, hooks, Playwright MCP, Figma to UI.", "status": "✔", "kind": "course", "id": "m09.claude-code-highly-agentic-coding"}, {"title": "Agent Skills with Anthropic", "creator": "DeepLearning.AI", "url": "https://www.deeplearning.ai/courses/agent-skills-with-anthropic", "link": "", "len": "10 lessons", "date": "2025–26", "cost": "Free", "why": "Skills across Claude.ai, Claude Code, the API and the Agent SDK.", "status": "✔", "kind": "course", "id": "m09.agent-skills-anthropic"}, {"title": "Claude Code video roadmap (Tech With Tim; Nick Saraev 4 h course and 3 h advanced course)", "creator": "developereducators.com", "url": "https://developereducators.com/roadmap/claude-code/", "link": "", "len": "20 videos", "date": "2026", "cost": "Free", "why": "A curated index of popular YouTube videos.", "status": "✔", "kind": "course", "id": "m09.claude-code-video-roadmap"}, {"title": "Claude Code docs", "creator": "Anthropic", "url": "https://code.claude.com/docs", "link": "", "len": "Reference", "date": "Continuously updated", "cost": "Free", "why": "**The source of truth.** Videos go out of date; the docs don't.", "status": "✔", "kind": "reading", "id": "m09.claude-code-docs"}, {"title": "Claude Code for Professional Developers", "creator": "Code with Mosh", "url": "", "link": "codewithmosh.com", "len": "~9 h", "date": "2026", "cost": "Paid (~$249 ≈ £200)", "why": "Only if you want one polished linear course. The free courses cover most of it.", "status": "◐", "kind": "course", "id": "m09.claude-code-professional-developers"}], "exercises": [{"text": "in an existing repo, set up a CLAUDE.md, a `/release-notes` skill, a lint-after-edit hook, a `security-reviewer` subagent and the Playwright MCP server. Then run a headless `claude -p` task from a shell script.", "id": "m09.ex1"}], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m10", "pos": 10, "phase": "p4", "title": "4.2 Alternatives & headless/CI", "week_label": "Week 11", "week": 11, "hours": 10, "video_min": 0, "vids": "No set videos: hands-on comparison with Gemini CLI and Codex, then Claude Code headless/CI docs", "core": false, "capstone": false, "body": "| Tool | Type | Entry price (Oct 2026) | Strengths | Weaknesses | Use it when… |\n| --- | --- | --- | --- | --- | --- |\n| Claude Code | Terminal/IDE/desktop agent | Pro $20; Max $100/$200 | Mature extension model; strong on long tasks; Agent SDK reuse | Claude models only; usage windows can cut you off mid-task; no free tier | Your main agent |\n| OpenAI Codex | Agent; open-source CLI (Apache-2.0) | Free and Go ($8) tiers; Plus $20 is the first plan that lists CLI/IDE; Pro from $100 | Open-source; cloud tasks; GPT-6-class models | Plan and credit rules change often | Second-opinion reviewer |\n| Gemini CLI | Open-source terminal agent | Free quota; paid via API | Generous free tier; 1M-token context | Quotas have changed before | Zero-cost experiments |\n| Cursor | AI IDE (VS Code fork) | Hobby free; Pro $20; Pro+ $60; Ultra $200 | Best editor UX; multi-model | Credits run out faster than the dollar figure suggests | If you prefer an IDE |\n| Windsurf | AI IDE | ~$20 | Similar to Cursor | Moved to daily/weekly quotas in March 2026, per a pricing tracker | Cursor alternative |\n| GitHub Copilot | IDE assistant + agent | Pro ~$10 | Cheapest paid option; built into GitHub | Less autonomous | Tight budget, team settings |\n| Replit Agent | Browser IDE + hosting | Free + paid | No setup; hosting included | In July 2025 the agent deleted a production database during a declared code freeze (1,206 executives, 1,196 companies). Replit then added dev/prod separation | Hosted prototypes |\n| Lovable / Bolt / v0 | Prompt-to-app builders | Free tiers + ~$20+ | Fastest from idea to clickable UI | CVE-2025-48757: a March 2025 scan of 1,645 apps from Lovable's showcase found about 10.3% with inadequate RLS | Demos and mockups. Export to GitHub and harden with Claude Code |\n\nPrice comparison checked 28 Sep 2026: https://www.developersdigest.tech/blog/ai-coding-tools-pricing-2026.\n\n**Recommendation:** pay for one $20 primary (Claude Pro), and use Gemini CLI (free) or a cheap Codex tier as the cross-checker. Upgrade to Max 5x only if you hit limits more than twice a week.", "items": [], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m11", "pos": 11, "phase": "p1", "title": "1.4B GitHub as the agents' operating system", "week_label": "Week 11", "week": 11, "hours": 3, "video_min": 90, "vids": "GitHub for Beginners: Issues & Projects 15 m · Actions 15 m · Security 15 m · Code review 15 m · GitHub Skills: Review PRs ~30 m · rulesets, gh and Claude Code Actions docs", "core": true, "capstone": false, "body": "**How the Claude–GitHub pieces fit:** `/install-github-app` from Claude Code installs the GitHub App, stores a secret and opens a pull request with the workflow files; you need the GitHub CLI installed and authenticated first. Mentioning `@claude` in an issue or PR comment has Claude analyse code, implement changes and push commits; a `prompt` input runs it automatically on any GitHub event, including a cron schedule. Boris Cherny, who created Claude Code, listed spinning up three to five worktrees each running its own session as his top tip in February 2026.", "items": [{"title": "GitHub for Beginners S3: Issues and Projects", "creator": "GitHub (Kedasha Kerr)", "url": "https://github.blog/developer-skills/github/github-for-beginners-getting-started-with-github-issues-and-projects/", "link": "https://github.blog/developer-skills/github/github-for-beginners-getting-started-with-github-issues-and-projects/ (video: https://youtu.be/c67GaAkf1BE)", "len": "~15 min + 8-min read", "date": "2 Mar 2026", "cost": "Free", "why": "**Primary.** Issue → board → PR with `Closes #n` auto-closing.", "status": "✔", "kind": "video", "id": "m11.github-beginners-issues-projects"}, {"title": "GitHub for Beginners S3: GitHub Actions", "creator": "GitHub (Kedasha Kerr)", "url": "https://github.blog/developer-skills/github/github-for-beginners-getting-started-with-github-actions/", "link": "", "len": "~15 min", "date": "16 Mar 2026", "cost": "Free", "why": "Your first workflow. Pairs with the Phase 5 CI work.", "status": "✔", "kind": "course", "id": "m11.github-beginners-github-actions"}, {"title": "GitHub for Beginners S3: GitHub security", "creator": "GitHub (Kedasha Kerr)", "url": "https://github.blog/developer-skills/github/github-for-beginners-getting-started-with-github-security/", "link": "", "len": "~15 min", "date": "30 Mar 2026", "cost": "Free", "why": "Secret scanning, push protection, Dependabot: the leaked-key fix from Phase 5.", "status": "✔", "kind": "course", "id": "m11.github-beginners-github-security"}, {"title": "GitHub for Beginners S2: Code review and refactoring with Copilot", "creator": "GitHub (Kedasha Kerr)", "url": "https://github.blog/ai-and-ml/github-copilot/github-for-beginners-code-review-and-refactoring-with-github-copilot/", "link": "", "len": "~15 min", "date": "9 Jun 2025", "cost": "Free", "why": "How AI review fits into human PR review. Copilot flavour, but the principles transfer to Claude.", "status": "✔", "kind": "course", "id": "m11.github-beginners-code-review-refactoring"}, {"title": "GitHub Skills: Review pull requests", "creator": "GitHub", "url": "https://github.com/skills", "link": "", "len": "<30 min", "date": "Current", "cost": "Free", "why": "Comment, suggest changes, apply, approve, merge, hands-on.", "status": "✔ exists", "kind": "course", "id": "m11.github-skills-review-pull-requests"}, {"title": "GitHub Docs: Reviewing pull requests; Rulesets", "creator": "GitHub", "url": "https://docs.github.com/en/pull-requests", "link": "https://docs.github.com/en/pull-requests · https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets", "len": "Reading", "date": "Current", "cost": "Free", "why": "Require a PR and passing checks before anything reaches `main`.", "status": "◐", "kind": "reading", "id": "m11.github-docs-reviewing-pull-requests"}, {"title": "GitHub CLI manual + \"Top gh commands\"", "creator": "GitHub; Adam Johnson", "url": "https://cli.github.com/manual/", "link": "https://cli.github.com/manual/ · https://adamj.eu/tech/2025/11/24/github-top-gh-cli-commands/", "len": "Reading", "date": "Current; 24 Nov 2025", "cost": "Free", "why": "`gh auth login`, `gh pr create/checkout/review`, `gh issue list`. No standout CLI video was found; the manual plus the exercise is the honest recommendation.", "status": "◐ / ✔ listed", "kind": "reading", "id": "m11.github-cli-manual-top-gh"}, {"title": "Claude Code GitHub Actions", "creator": "Anthropic", "url": "https://code.claude.com/docs/en/github-actions", "link": "", "len": "Reading", "date": "Current", "cost": "Free (uses your subscription or API)", "why": "`/install-github-app`, `@claude`, review workflow, scheduled runs, cost caps.", "status": "✔", "kind": "reading", "id": "m11.claude-code-github-actions"}, {"title": "Claude Code: Code Review", "creator": "Anthropic", "url": "https://code.claude.com/docs/en/code-review", "link": "", "len": "Reading", "date": "Current", "cost": "Free", "why": "Automatic review on every PR with no workflow file.", "status": "◐", "kind": "reading", "id": "m11.claude-code-code-review"}, {"title": "Claude Code + Git worktrees guide", "creator": "devtoollab", "url": "https://devtoollab.com/blog/claude-code-git-worktrees-parallel-agents-guide", "link": "", "len": "Reading", "date": "2026", "cost": "Free", "why": "`claude --worktree` (shipped v2.1.49, Feb 2026), `.worktreeinclude`, subagent isolation. A video titled \"Claude Code Worktrees in 7 Minutes\" also exists, creator unverified.", "status": "✔ / ◐", "kind": "reading", "id": "m11.claude-code-git-worktrees-guide"}], "exercises": [{"text": "**Issues as an agent queue.** Create three issues, a Kanban project and labels. Have Claude Code pick up issue #1 on a branch and open a PR whose description says `Closes #1`. Review it yourself: leave an inline comment, request a change, approve, squash-merge, and watch the issue close.", "id": "m11.ex1"}, {"text": "**Lock the door.** Add a ruleset requiring a PR, one approval and a passing check before merging to `main`. Turn on secret scanning and push protection, then try to push a fake API key and watch it get blocked.", "id": "m11.ex2"}, {"text": "**Wire in Claude.** Run `/install-github-app`, comment `@claude` on an issue, and read the review Claude leaves on your next PR. Notice what it catches and what it misses.", "id": "m11.ex3"}], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m12", "pos": 12, "phase": "p5", "title": "5 Next.js, Supabase, Stripe, deploy", "week_label": "Weeks 12–15", "week": 15, "hours": 36, "video_min": 650, "vids": "SaaS Full Course 2026 3 h 56 m · Next.js 13 & Supabase playlists ~4 h · Docker concepts 10 m · Essentials: dev containers & Actions ~2 h · Actions 15 m · Next.js Learn ~8–10 h (text tutorial)", "core": true, "capstone": false, "body": "", "items": [{"title": "SaaS App Full Course 2026 – Launch Your SaaS in Under 7 Days with Next JS, Supabase & Payments", "creator": "JavaScript Mastery", "url": "https://www.youtube.com/watch?v=XUkNR-JfHwo", "link": "", "len": "3 h 56 m", "date": "uploaded 23 May 2025 (retitled 2026)", "cost": "Free", "why": "**Primary end-to-end build.** Payments use Clerk Billing, not Stripe, so add Stripe from its docs.", "status": "✔", "kind": "video", "id": "m12.saas-app-full-course-2026"}, {"title": "Next.js Learn", "creator": "Vercel", "url": "https://nextjs.org/learn", "link": "", "len": "~8–10 h", "date": "Continuously updated", "cost": "Free", "why": "The current official App Router tutorial.", "status": "◐", "kind": "course", "id": "m12.next-js-learn"}, {"title": "Next.js 13 Crash Course", "creator": "Net Ninja", "url": "https://www.youtube.com/watch?v=TJQbDPGzm0Y", "link": "", "len": "playlist", "date": "~2023 (older; some APIs have changed)", "cost": "Free", "why": "Clear teaching. Pair it with the docs.", "status": "✔ exists", "kind": "video", "id": "m12.next-js-13-crash-course"}, {"title": "Supabase Tutorial for Beginners", "creator": "Net Ninja", "url": "https://www.youtube.com/channel/UCW5YeuERMmlnqo4oq8vwUpg", "link": "", "len": "playlist", "date": "~2022 (older)", "cost": "Free", "why": "The Supabase mental model. Neon (https://neon.com/docs) is the alternative if you don't want bundled auth.", "status": "✔ exists (URL not confirmed)", "kind": "video", "id": "m12.supabase-tutorial-beginners"}, {"title": "Supabase docs – RLS and Auth", "creator": "Supabase", "url": "https://supabase.com/docs/guides/database/postgres/row-level-security", "link": "", "len": "Reference", "date": "Current", "cost": "Free", "why": "**Mandatory.** The single most important security setting for vibe-coded apps.", "status": "◐", "kind": "reading", "id": "m12.supabase-docs-rls-auth"}, {"title": "Stripe docs – Checkout, Billing, webhooks", "creator": "Stripe", "url": "https://docs.stripe.com", "link": "", "len": "Reference", "date": "Current", "cost": "Fees per transaction", "why": "Use Checkout and the Customer Portal; never build your own payment UI.", "status": "◐", "kind": "reading", "id": "m12.stripe-docs-checkout-billing-webhooks"}, {"title": "Vercel / Railway / Fly.io / Cloudflare docs", "creator": "Vendors", "url": "https://vercel.com/docs", "link": "https://vercel.com/docs · https://docs.railway.com · https://fly.io/docs · https://developers.cloudflare.com", "len": "Reference", "date": "Current", "cost": "Free tiers", "why": "Vercel for Next.js; Railway/Fly for workers and agents; Cloudflare for DNS and edge.", "status": "◐", "kind": "reading", "id": "m12.vercel-railway-fly-io-cloudflare"}, {"title": "100+ Docker Concepts you Need to Know", "creator": "Fireship", "url": "https://www.youtube.com/@Fireship", "link": "search the title on https://www.youtube.com/@Fireship", "len": "~10 min", "date": "~2024 (older, foundational)", "cost": "Free", "why": "Enough to containerise an agent worker.", "status": "✔ exists (URL not confirmed)", "kind": "video", "id": "m12.100-docker-concepts-you-need"}, {"title": "Claude Code Essentials – dev containers & GitHub Actions", "creator": "freeCodeCamp", "url": "https://www.freecodecamp.org/news/claude-code-essentials/", "link": "", "len": "~2 h of 12", "date": "Mar 2026", "cost": "Free", "why": "Running the agent inside CI.", "status": "✔", "kind": "course", "id": "m12.claude-code-essentials-dev-containers"}, {"title": "GitHub for Beginners S3: GitHub Actions", "creator": "GitHub (Kedasha Kerr)", "url": "https://github.blog/developer-skills/github/github-for-beginners-getting-started-with-github-actions/", "link": "", "len": "~15 min", "date": "16 Mar 2026", "cost": "Free", "why": "Your first workflow, before you add tests to it.", "status": "✔", "kind": "course", "id": "m12.github-beginners-github-actions"}, {"title": "GitHub Actions docs; OWASP Top 10 (+ LLM Top 10)", "creator": "GitHub; OWASP", "url": "https://docs.github.com/actions", "link": "https://docs.github.com/actions · https://owasp.org", "len": "Reference", "date": "Current", "cost": "Free", "why": "Run tests on every PR, and have Claude audit your app against OWASP.", "status": "◐", "kind": "reading", "id": "m12.github-actions-docs-owasp-top"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m13", "pos": 13, "phase": "p5", "title": "5 Security for vibe-coded apps", "week_label": "Week 16", "week": 16, "hours": 6, "video_min": 0, "vids": "Reading and an audit exercise: RLS, keys, prod access, injection, webhooks (OWASP Top 10)", "core": true, "capstone": false, "body": "1. **No RLS.** In the Lovable case (CVE-2025-48757), Matt Palmer's statement (29 May 2025) reports that his 21 March 2025 scan found 303 endpoints across 170 of 1,645 projects (about 10.3%) with inadequate RLS settings. **Fix:** turn on RLS for every table, write policies based on `auth.uid()`, and test while logged out.\n2. **Leaked keys.** The `service_role` key or API keys end up in front-end code or Git. **Fix:** keep them in server-only env vars, put `.env` in `.gitignore`, turn on GitHub push protection (see Module 1.4), and rotate anything that has leaked.\n3. **Agents with production access.** This is what happened with Replit and SaaStr. **Fix:** separate dev and prod databases, give agents a read-only prod role, keep backups, and add a hook that blocks destructive SQL.\n4. **Injection.** SQL injection and prompt injection through user content. **Fix:** use parameterised queries or an ORM, and treat everything the model reads as untrusted.\n5. **Unverified webhooks.** **Fix:** verify Stripe signatures and make handlers idempotent (safe to run twice).\n\n**Monitoring:** Sentry, platform logs and PostHog all have free tiers.", "items": [], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m14", "pos": 14, "phase": "p5", "title": "Capstone 1: paid micro-SaaS live", "week_label": "Week 16", "week": 16, "hours": 18, "video_min": 0, "vids": "Build time, no videos", "core": true, "capstone": true, "body": "", "items": [], "exercises": [{"text": "a Next.js + Supabase + Stripe app that solves a problem from your sales world, such as an account-research brief generator. It needs auth and RLS, a Stripe subscription (test mode, then live), CI on every PR with a ruleset protecting `main`, Sentry and a custom domain, and it launches to 10 people.", "label": "Capstone 1 (paid micro-SaaS)", "id": "m14.ex1"}], "ready": "a stranger can sign up, pay, use the app and cancel; logged-out queries to every table return nothing; CI blocks a failing test; and you can draw the architecture from memory.", "pitfalls": "building your own auth or payments, skipping test mode, and launching without backups.", "changed_in": 1}, {"key": "m15", "pos": 15, "phase": "p6", "title": "6.1 APIs, tool use, the agent loop", "week_label": "Weeks 17–18", "week": 18, "hours": 12, "video_min": 690, "vids": "DLAI Agentic AI 9 h 55 m (31 videos) · Building toward Computer Use 1 h 35 m · Building effective agents 30 m (reading) · optional: Certified Developer prep ~8 h", "core": true, "capstone": false, "body": "", "items": [{"title": "Agentic AI", "creator": "Andrew Ng / DeepLearning.AI", "url": "https://www.deeplearning.ai/courses/agentic-ai", "link": "", "len": "9 h 55 m, 31 videos", "date": "launched 7 Oct 2025, updated 31 Aug 2026", "cost": "Free to watch; certificate needs Pro", "why": "**Primary, vendor-neutral.** Reflection, tool use, planning, multi-agent systems, evals, error analysis.", "status": "✔", "kind": "course", "id": "m15.agentic-ai"}, {"title": "Building effective agents", "creator": "Anthropic (Erik Schluntz & Barry Zhang)", "url": "https://www.anthropic.com/engineering/building-effective-agents", "link": "", "len": "~30 min", "date": "Dec 2024 (older, foundational)", "cost": "Free", "why": "The canonical patterns: chaining, routing, parallelisation, orchestrator-workers, evaluator-optimiser, then autonomous agents. Start simple.", "status": "◐", "kind": "course", "id": "m15.building-effective-agents"}, {"title": "Claude Certified Developer Foundations prep course", "creator": "freeCodeCamp", "url": "https://www.freecodecamp.org/news/unlock-the-power-of-ai-agents-with-the-new-claude-certified-developer-foundations-course/", "link": "", "len": "~8 h", "date": "2026", "cost": "Free", "why": "Agent architectures, MCP, JSON outputs, caching, prompt-injection defence, cost.", "status": "✔", "kind": "course", "id": "m15.claude-certified-developer-foundations-prep"}, {"title": "Building toward Computer Use with Anthropic", "creator": "DeepLearning.AI (Colt Steele)", "url": "https://www.deeplearning.ai/courses", "link": "", "len": "1 h 35 m", "date": "2025", "cost": "Free", "why": "API basics up to computer use. Model names are older.", "status": "✔ listed", "kind": "course", "id": "m15.building-toward-computer-use-anthropic"}], "exercises": [{"text": "write an agent loop by hand in about 80 lines of Python: messages → model → tool call → your code runs it → append the result → repeat. Add a max-steps limit and a cost counter. After this, every framework makes sense.", "id": "m15.ex1"}], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m16", "pos": 16, "phase": "p6", "title": "6.2 Model Context Protocol", "week_label": "Week 19", "week": 19, "hours": 10, "video_min": 98, "vids": "DLAI MCP: Build Rich-Context AI Apps 1 h 38 m · Hugging Face MCP course (several h, mixed) · modelcontextprotocol.io", "core": true, "capstone": false, "body": "", "items": [{"title": "MCP: Build Rich-Context AI Apps with Anthropic", "creator": "DeepLearning.AI (Elie Schoppik)", "url": "https://www.deeplearning.ai/courses/mcp-build-rich-context-ai-apps-with-anthropic", "link": "", "len": "1 h 38 m, 11 videos", "date": "May 2025", "cost": "Free", "why": "**Primary:** build both a server and a client.", "status": "✔", "kind": "course", "id": "m16.mcp-build-rich-context-ai"}, {"title": "MCP Course (with Anthropic)", "creator": "Hugging Face", "url": "https://huggingface.co/learn/mcp-course/en/unit0/introduction", "link": "", "len": "multi-unit", "date": "2025 (now \"legacy\")", "cost": "Free + free certificate", "why": "Theory → end-to-end app → deployed use case.", "status": "✔", "kind": "course", "id": "m16.mcp-course"}, {"title": "The Context Course", "creator": "Hugging Face", "url": "https://huggingface.co/context-course", "link": "", "len": "multi-unit", "date": "2026", "cost": "Free", "why": "Skills, plugins, MCP, subagents and hooks across Claude Code, Codex and OpenCode.", "status": "✔", "kind": "course", "id": "m16.context-course"}, {"title": "modelcontextprotocol.io", "creator": "MCP project", "url": "https://modelcontextprotocol.io", "link": "", "len": "Reference", "date": "Current", "cost": "Free", "why": "The spec and SDKs. Claude Academy's MCP intro and advanced courses are official, shorter alternatives.", "status": "◐", "kind": "reading", "id": "m16.modelcontextprotocol-io"}], "exercises": [{"text": "build a read-only MCP server for your Phase 5 app and connect it to Claude Code and one other client.", "id": "m16.ex1"}], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m17", "pos": 17, "phase": "p6", "title": "6.3 Frameworks compared", "week_label": "Week 20", "week": 20, "hours": 12, "video_min": 0, "vids": "No set videos: build the same agent in two frameworks and compare", "core": false, "capstone": false, "body": "**Recommendation:** start with the plain API and your own hand-written loop. Then add the Claude Agent SDK (it matches your Claude Code skills) and the Vercel AI SDK (multi-provider, which hedges vendor risk). Add LangGraph only when you need durable, branching workflows with approvals.", "items": [{"title": "Claude Agent SDK", "creator": "Py/TS", "url": "https://code.claude.com/docs/en/agent-sdk/overview", "link": "https://code.claude.com/docs/en/agent-sdk/overview ✔", "len": "", "date": "", "cost": "", "why": "Best for: Claude Code's harness inside your own app. Watch-outs: Claude-only; no longer uses Claude Code's system prompt by default.", "status": "✔", "kind": "course", "id": "m17.claude-agent-sdk"}, {"title": "OpenAI Agents SDK", "creator": "Py/TS", "url": "https://openai.github.io/openai-agents-python/", "link": "https://openai.github.io/openai-agents-python/ ◐; James Briggs, \"Agents SDK from OpenAI! Full Tutorial\" https://www.youtube.com/watch?v=35nxORG1mtg (~22 min, ~Mar 2025) + playlist https://www.youtube.com/playlist?list=PLIUOU7oqGTLjsFQaIyhcC1u2Nu1MmBTbs ✔", "len": "", "date": "", "cost": "", "why": "Best for: Lightweight handoffs, guardrails, tracing. Watch-outs: Built around OpenAI.", "status": "✔", "kind": "video", "id": "m17.openai-agents-sdk"}, {"title": "LangGraph", "creator": "Py/TS", "url": "https://academy.langchain.com/courses/intro-to-langgraph", "link": "LangChain Academy \"Introduction to LangGraph\" (free) https://academy.langchain.com/courses/intro-to-langgraph ✔ (Sep 2024; older, foundational)", "len": "", "date": "", "cost": "", "why": "Best for: Durable state machines, human-in-the-loop. Watch-outs: Steeper learning curve.", "status": "✔", "kind": "course", "id": "m17.langgraph"}, {"title": "Pydantic AI", "creator": "Python", "url": "https://ai.pydantic.dev", "link": "https://ai.pydantic.dev ◐", "len": "", "date": "", "cost": "", "why": "Best for: Type-safe structured outputs. Watch-outs: Smaller ecosystem.", "status": "◐", "kind": "course", "id": "m17.pydantic-ai"}, {"title": "CrewAI", "creator": "Python", "url": "https://docs.crewai.com", "link": "https://docs.crewai.com ◐", "len": "", "date": "", "cost": "", "why": "Best for: Quick role-based multi-agent prototypes. Watch-outs: Harder to control precisely.", "status": "◐", "kind": "course", "id": "m17.crewai"}, {"title": "Google ADK", "creator": "Py/Java/TS", "url": "https://google.github.io/adk-docs", "link": "https://google.github.io/adk-docs ◐", "len": "", "date": "", "cost": "", "why": "Best for: Gemini/Vertex deployments. Watch-outs: Pulls you towards Google Cloud.", "status": "◐", "kind": "course", "id": "m17.google-adk"}, {"title": "Mastra", "creator": "TypeScript", "url": "https://mastra.ai/docs", "link": "https://mastra.ai/docs ◐", "len": "", "date": "", "cost": "", "why": "Best for: TS-native agents for Next.js teams. Watch-outs: Younger project.", "status": "◐", "kind": "course", "id": "m17.mastra"}, {"title": "Vercel AI SDK", "creator": "TypeScript", "url": "https://ai-sdk.dev/docs", "link": "https://ai-sdk.dev/docs ◐", "len": "", "date": "", "cost": "", "why": "Best for: Streaming chat/tool UIs, multi-provider. Watch-outs: A plumbing layer, not an orchestrator.", "status": "◐", "kind": "course", "id": "m17.vercel-ai-sdk"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m18", "pos": 18, "phase": "p6", "title": "6.4 Evals, observability, RAG, guardrails", "week_label": "Week 21", "week": 21, "hours": 26, "video_min": 0, "vids": "Evals modules of DLAI Agentic AI (already counted in 6.1) · Langfuse/LangSmith, pgvector and guardrail docs", "core": true, "capstone": false, "body": "**Cost controls:** a budget cap per run, a max-steps limit, a cheap model for routing, prompt caching, cost logged per task, and alerts at 50%, 80% and 100% of the monthly budget.", "items": [{"title": "Evals: Agentic AI (Ng), evals module", "creator": "", "url": "https://www.deeplearning.ai/courses/agentic-ai", "link": "", "len": "", "date": "", "cost": "", "why": "Build an eval set *before* you tune prompts", "status": "✔", "kind": "course", "id": "m18.evals-agentic-ai-evals-module"}, {"title": "Observability: Langfuse (open-source); alternatives LangSmith, Braintrust", "creator": "", "url": "https://langfuse.com/docs", "link": "https://langfuse.com/docs · https://docs.smith.langchain.com · https://www.braintrust.dev/docs", "len": "", "date": "", "cost": "", "why": "Traces, cost, prompt versions", "status": "◐", "kind": "course", "id": "m18.observability-langfuse-alternatives"}, {"title": "RAG: Supabase pgvector", "creator": "", "url": "https://supabase.com/docs/guides/ai", "link": "", "len": "", "date": "", "cost": "", "why": "Use pgvector in the Postgres you already run before adding a separate vector DB", "status": "◐", "kind": "course", "id": "m18.rag-supabase-pgvector"}, {"title": "Memory/context: Anthropic context engineering", "creator": "", "url": "https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents", "link": "", "len": "", "date": "", "cost": "", "why": "Compaction, note-taking, isolating context in subagents", "status": "✔", "kind": "course", "id": "m18.memory-context-anthropic-context-engineering"}, {"title": "Guardrails: freeCodeCamp CCDV-F course; OWASP LLM Top 10", "creator": "", "url": "", "link": "links above", "len": "", "date": "", "cost": "", "why": "Least privilege, allow-listed tools, human approval for any write", "status": "✔ / ◐", "kind": "course", "id": "m18.guardrails-freecodecamp-ccdv-f-course"}, {"title": "Computer use & browser agents: DLAI Computer Use; Playwright MCP", "creator": "", "url": "", "link": "links above", "len": "", "date": "", "cost": "", "why": "Slow and brittle. Use APIs where they exist", "status": "✔", "kind": "course", "id": "m18.computer-use-browser-agents-dlai"}, {"title": "Background agents: Agent SDK hosting docs; Railway/Fly workers", "creator": "", "url": "https://code.claude.com/docs/en/agent-sdk/overview", "link": "", "len": "", "date": "", "cost": "", "why": "Queue workers with checkpoints, timeouts and budgets", "status": "✔ / ◐", "kind": "course", "id": "m18.background-agents-agent-sdk-hosting"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m19", "pos": 19, "phase": "p6", "title": "Capstone 2: production agent", "week_label": "Week 22", "week": 22, "hours": null, "video_min": 0, "vids": "Budget sits inside Module 6.4's 26 h", "core": true, "capstone": true, "body": "", "items": [], "exercises": [{"text": "a prospect-research agent that takes a company name, uses web search and your MCP server, and writes a structured brief to Supabase. It needs 30 eval cases, Langfuse tracing, a cost cap, and human approval before any email is sent.", "label": "Capstone 2 (production agent)", "id": "m19.ex1"}], "ready": "the agent passes at least 90% of your evals, every run is traced with its cost, and you can show a blocked prompt-injection attempt.", "pitfalls": "going multi-agent before a single agent works, skipping evals, and giving agents write access to email or the CRM on day one.", "changed_in": 1}, {"key": "m20", "pos": 20, "phase": "p7", "title": "7 n8n, integrations, multi-agent, HITL", "week_label": "Weeks 23–24", "week": 24, "hours": 20, "video_min": 315, "vids": "n8n Tutorial for Beginners playlist, 10 videos ~3 h · Master n8n in 2 Hours 2 h · Selling to AI Agents 14 m · optional: Ultimate n8n Course 17 h", "core": true, "capstone": false, "body": "#### The \"AI-run business\" reference stack\n\n| Layer | Tooling | Human control point |\n| --- | --- | --- |\n| Inbox/triage | n8n + Gmail/Outlook + a cheap classifier model | You approve outbound replies |\n| CRM ops | HubSpot/Attio/Pipedrive via API or MCP | Agents draft; you bulk-approve |\n| Research & content | Agent SDK workers on a schedule | Editorial queue in Notion/Slack |\n| Engineering | GitHub Issues → Claude Code (`@claude` or headless in Actions) → PR | You review and merge; rulesets block direct pushes to `main` |\n| Finance/reporting | Stripe + Supabase → weekly report agent | Read-only access |\n| Observability | Langfuse + Sentry + Slack alerts | A kill switch for each workflow |\n\n**On \"a company that builds companies\":** a realistic 2026 design is a pipeline. Each stage is a well-specified workflow with evals, and each hands off to the next.\n\n1. An idea-research agent finds candidate ideas.\n2. A validation step scores each market.\n3. A landing page and waitlist go up.\n4. Agents draft outreach.\n5. **You** make the go/no-go call.\n6. Claude Code builds the MVP from a spec template.\n7. A launch checklist runs.\n\nAgents can take on much of the *work* at each stage, but not the *judgement*. The Replit and Lovable incidents show what happens when the human checkpoints are removed.", "items": [{"title": "n8n Tutorial for Beginners – The Complete Course", "creator": "YouTube playlist (creator not confirmed)", "url": "https://www.youtube.com/playlist?list=PLYLEmQupIzOEEvgtBduSgYLaug7LKqlSo", "link": "", "len": "10 videos", "date": "2025", "cost": "Free", "why": "**Primary structured intro.**", "status": "✔ exists", "kind": "video", "id": "m20.n8n-tutorial-beginners-complete-course"}, {"title": "Master n8n in 2 Hours: Complete Beginner's Guide for 2026", "creator": "YouTube (Automatable)", "url": "https://www.youtube.com/watch?v=AURnISajubk", "link": "", "len": "~2 h", "date": "2026", "cost": "Free", "why": "The fastest current alternative.", "status": "✔ exists", "kind": "video", "id": "m20.master-n8n-2-hours-complete"}, {"title": "Ultimate n8n Course: Beginner to Pro in 17 Hours (2026)", "creator": "YouTube (creator not confirmed)", "url": "https://www.youtube.com/watch?v=TZ43SRdTMs0", "link": "", "len": "~17 h", "date": "2026", "cost": "Free", "why": "The deep option: sub-workflows, agent tools, schema validation.", "status": "✔ exists", "kind": "video", "id": "m20.ultimate-n8n-course-beginner-pro"}, {"title": "n8n docs", "creator": "n8n", "url": "https://docs.n8n.io", "link": "", "len": "Reference", "date": "Current", "cost": "Free to self-host", "why": "Self-host it on Railway or Hetzner.", "status": "◐", "kind": "reading", "id": "m20.n8n-docs"}, {"title": "Make / Zapier help", "creator": "Make, Zapier", "url": "https://www.make.com/en/help", "link": "https://www.make.com/en/help · https://help.zapier.com", "len": "Reference", "date": "Current", "cost": "Free tiers", "why": "**For balance:** Zapier is quickest for colleagues, Make is cheaper for complex flows, n8n gives the most control.", "status": "◐", "kind": "reading", "id": "m20.make-zapier-help"}, {"title": "Claude Code GitHub Actions – scheduled runs", "creator": "Anthropic", "url": "https://code.claude.com/docs/en/github-actions", "link": "", "len": "Reading", "date": "Current", "cost": "Free", "why": "A `prompt` on a cron schedule, e.g. a daily report from commits and open issues, with `--max-turns` and tool allow-lists as the cost cap.", "status": "✔", "kind": "reading", "id": "m20.claude-code-github-actions-scheduled"}, {"title": "The Next $100B Market: Selling to AI Agents", "creator": "Greg Isenberg", "url": "https://www.youtube.com/watch?v=MlptIfpoLlw", "link": "", "len": "~14 min", "date": "2 Jun 2026", "cost": "Free", "why": "Business models for agent-native companies. Related episodes: Allie K. Miller, \"How to Build an AI-Native Company in 2026\" (12 Aug 2026); Ryan Carson, \"Most Valuable Skill of 2026: Managing AI Agents\" (24 Jul 2026).", "status": "✔", "kind": "video", "id": "m20.next-100b-market-selling-ai"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m21", "pos": 21, "phase": "p7", "title": "Capstone 3: multi-agent ops system", "week_label": "Week 25", "week": 25, "hours": 10, "video_min": 0, "vids": "Build time, no videos", "core": true, "capstone": true, "body": "", "items": [], "exercises": [{"text": "three agents (triage, research, reporting) orchestrated by n8n or LangGraph, with a shared Supabase state table, approvals posted to Slack, schedules, Langfuse traces and a monthly budget cap.", "label": "Capstone 3 (multi-agent ops system)", "id": "m21.ex1"}], "ready": "the system runs unattended for 7 days, every external action has gone through an approval, and a runbook exists.", "pitfalls": "automating a process you've never done by hand, letting agents talk to customers unsupervised, and ignoring GDPR when sending personal data to model vendors.", "changed_in": 1}, {"key": "m22", "pos": 22, "phase": "p8", "title": "8 Shipping, product, compliance", "week_label": "Weeks 25–26", "week": 25, "hours": 20, "video_min": 150, "vids": "Greg Isenberg episodes you pick ~2–3 h · PostHog, ICO and EU AI Act reading", "core": true, "capstone": false, "body": "#### UK/EU compliance essentials\n\nThe Digital Omnibus on AI (Regulation (EU) 2026/1744, published in the Official Journal on 24 July 2026) entered into force on 27 July 2026, according to the European Commission's notice \"AI Omnibus enters into force\". It changed the timetable:\n\n| Obligation | Applies from |\n| --- | --- |\n| Annex III high-risk systems (employment, credit scoring, education, biometrics, critical infrastructure) | 2 December 2027 (moved from 2 August 2026) |\n| Annex I AI embedded in regulated products | 2 August 2028 |\n| Article 50 transparency: disclose AI interactions, label AI-generated content | 2 August 2026 (already applies) |\n| Machine-readable marking for generative systems already on the market | 2 December 2026 (grace period ends) |\n\n**What this means for you:** if EU users can talk to your agent, disclose that it's AI now, and avoid hiring or credit-scoring use cases for the time being.\n\n**UK:** there is no UK equivalent of the AI Act. UK GDPR and ICO guidance apply: a lawful basis for processing, a privacy notice, a data processing agreement with every AI vendor, and data minimisation before anything is sent to a model. This is orientation, not legal advice. Get a solicitor to review before you process customer personal data at scale.", "items": [{"title": "AI-native business models: Greg Isenberg (Startup Ideas Podcast, 380+ episodes)", "creator": "", "url": "https://www.youtube.com/@GregIsenberg", "link": "", "len": "", "date": "", "cost": "", "why": "", "status": "✔", "kind": "video", "id": "m22.ai-native-business-models-greg"}, {"title": "Product analytics: PostHog docs", "creator": "", "url": "https://posthog.com/docs", "link": "", "len": "", "date": "", "cost": "", "why": "", "status": "◐", "kind": "course", "id": "m22.product-analytics-posthog-docs"}, {"title": "UK GDPR: ICO guidance", "creator": "", "url": "https://ico.org.uk/for-organisations/", "link": "", "len": "", "date": "", "cost": "", "why": "", "status": "◐", "kind": "course", "id": "m22.uk-gdpr-ico-guidance"}, {"title": "EU AI Act: European Commission", "creator": "", "url": "https://digital-strategy.ec.europa.eu", "link": "", "len": "", "date": "", "cost": "", "why": "", "status": "◐", "kind": "course", "id": "m22.eu-ai-act-european-commission"}], "exercises": [], "ready": "", "pitfalls": "", "changed_in": 1}, {"key": "m23", "pos": 23, "phase": "p8", "title": "Capstone 4: real launch", "week_label": "Week 26", "week": 26, "hours": 30, "video_min": 0, "vids": "Customer conversations, launch and iteration; no videos", "core": true, "capstone": true, "body": "", "items": [], "exercises": [{"text": "20 customer conversations to validate the idea, charging from day one, a landing page with a waitlist, a public launch, and either 10 paying customers or a written decision to kill it. Capstone 3 runs operations behind it.", "label": "Capstone 4 (real launch)", "id": "m23.ex1"}], "ready": "", "pitfalls": "", "changed_in": 1}]$cc$::jsonb)
